import json,re
from pathlib import Path
rows=[]
def add(topic,title,before,after,keys,hint,why,cursor=(0,0)):
    tokens=re.findall(r'<(?:Esc|Enter|C-[a-z])>|.',keys)
    rows.append([topic,title,before,after,list(cursor),tokens,hint,why])
def macro(title,before,after,body,hint,why,count=2,register='a',cursor=(0,0)):
    add('Macros',title,before,after,'q'+register+body+'q'+str(count)+'@'+register,hint,why,cursor)
# Twenty macro exercises: different row shapes and useful compound transformations.
macro('Turn the filenames into shell copy commands.','report.csv\nannual-summary.csv\nnotes.txt','cp report.csv backup/\ncp annual-summary.csv backup/\ncp notes.txt backup/','Icp <Esc>A backup/<Esc>j0','Record Icp, Escape, A backup/, Escape, then j0. Replay on the other two lines.','I and A anchor the transformation to each row, so filename length does not matter.')
macro('Convert each hostname into an HTTPS URL.','api.example.com\nstatus.example.com\ndocs.example.com','https://api.example.com/\nhttps://status.example.com/\nhttps://docs.example.com/','Ihttps://<Esc>A/<Esc>j0','Record a prefix with I, a suffix with A, and j0 to prepare the next host.','A good macro ends where the next repetition needs to begin.')
macro('Remove the log timestamp and its following space from each line.','09:01 INFO boot\n09:02 WARN retry\n09:03 INFO ready','INFO boot\nWARN retry\nINFO ready','dWj0','Record dW followed by j0, then replay twice.','W treats the colon-containing timestamp as one whitespace-delimited field; a small-word motion would stop inside it.')
macro('Strip the leading “key=” field from each record.','user=ada\nteam=platform\nregion=west','ada\nplatform\nwest','df=j0','Record df= and j0. Replay on the remaining records.','Finding the delimiter is more robust than deleting a fixed number of characters.')
macro('Remove the trailing comments from all three settings.','port=8080 # local\nworkers=4 # concurrency\ncache=true # fast','port=8080\nworkers=4\ncache=true','f Dj0','Record f followed by Space, D, then j0.','The first space marks the comment boundary. D removes the separator along with the comment.')
macro('Replace every quoted token with “REDACTED”.','token="abc"\nsecret="long-private-value"\nkey="xyz"','token="REDACTED"\nsecret="REDACTED"\nkey="REDACTED"','ci"REDACTED<Esc>j0','Record ci"REDACTED, Escape, and j0.','The quote object handles different secret lengths and leaves both delimiters intact.')
macro('Clear the arguments in all three calls.','refresh(cache)\nnotify(user, message)\nflush(buffer, true)','refresh()\nnotify()\nflush()','f(di(j0','Record f(, di(, and j0.','Each replay finds its own opening parenthesis before editing the contents.')
macro('Convert each name into a zero-argument call.','start\nrefreshCache\nstop','start();\nrefreshCache();\nstop();','A();<Esc>j0','Record A();, Escape, then j0.','The macro combines an edit with movement; dot alone would still require you to navigate between rows.')
macro('Comment out the three selected configuration lines.','port=8080\nworkers=4\ncache=true\nkeep=true','# port=8080\n# workers=4\n# cache=true\nkeep=true','I# <Esc>j0','Record I# and a space, Escape, j0; replay exactly twice.','A counted replay limits the change to the intended rows. The fourth setting is deliberately untouched.')
macro('Uncomment the three commands, keeping the footer.','# build\n# test\n# deploy\n# end','build\ntest\ndeploy\n# end','0xxj','Record 0xxj and replay twice.','Here the prefix is exactly two characters on every row, so a fixed-width deletion is appropriate.')
macro('Lowercase the status field in each record.','READY api\nFAILED worker\nWAITING queue','ready api\nfailed worker\nwaiting queue','guiwj0','Record guiw followed by j0.','The word object limits the case change to the status and preserves the service name.')
macro('Change the first colon in each mapping to an equals sign.','host:localhost\nport:8080\nurl:https://example.com','host=localhost\nport=8080\nurl=https://example.com','f:r=j0','Record f:r= and j0.','Finding the first delimiter leaves later colons, such as the URL scheme, intact.')
macro('Add a Markdown checkbox before every task.','write tests\nreview migration\nship release','- [ ] write tests\n- [ ] review migration\n- [ ] ship release','I- [ ] <Esc>j0','Record I- [ ] and a space, Escape, then j0.','A recorded insertion can contain punctuation and spaces as well as words.')
macro('Remove the “export ” prefix from each environment variable.','export HOST=localhost\nexport PORT=8080\nexport MODE=dev','HOST=localhost\nPORT=8080\nMODE=dev','dawj0','Record daw and j0.','The around-word object removes the prefix together with the space it owns.')
macro('Increase the first number in each release row by one.','7 api\n19 worker\n99 scheduler','8 api\n20 worker\n100 scheduler','<C-a>j0','Record Ctrl+a and j0.','Numeric editing handles carries, so the same macro works across different digit lengths.')
macro('Reduce each retry budget by two.','5 api\n12 worker\n100 queue','3 api\n10 worker\n98 queue','2<C-x>j0','Record 2 Ctrl+x and j0.','Counts apply inside a macro as well as to the number of macro replays.')
macro('Wrap each label in square brackets.','info\nwarning\nerror','[info]\n[warning]\n[error]','I[<Esc>A]<Esc>j0','Record I[, Escape, A], Escape, j0.','Using both line boundaries avoids assumptions about label length.')
macro('Replace the first CSV field with “archived”.','active,ada,12\npending,lin,4\nblocked,lee,8','archived,ada,12\narchived,lin,4\narchived,lee,8','ct,archived<Esc>j0','Record ct,archived, Escape, and j0.','The till motion keeps the comma while changing a variable-length field.')
add('Macros','Prefix all four commands with “sudo ”.','install app\nrestart api\nreload proxy\ncheck health','sudo install app\nsudo restart api\nsudo reload proxy\nsudo check health','qaIsudo <Esc>j0q@a2@@','Record the prefix and j0 in a. @a runs it, and @@ repeats the last-used macro.','@@ remembers the last executed register. A count can replay that same macro several times; stop at the requested scope.')
macro('Use register b to turn the paths into include directives.','core.h\nnetwork.h\nstorage.h','#include "core.h"\n#include "network.h"\n#include "storage.h"','I#include "<Esc>A"<Esc>j0','Record with qb, insert the surrounding directive, finish with j0, then use 2@b.','Macros can live in any named register. Choosing b leaves a available for another routine.',register='b')
# Twenty search tasks: boundaries, direction, anchors and deliberate match selection.
def search(title,before,after,keys,hint,why,cursor=(0,0)):
    add('Search',title,before,after,keys,hint,why,cursor)
search('Rename the “timeout” setting to “deadline”.','host=local\nretries=3\ntimeout=30\nport=8080','host=local\nretries=3\ndeadline=30\nport=8080','/timeout<Enter>ciwdeadline<Esc>','Search for timeout, then change the word with ciw.','Search locates the setting without counting lines; the word object preserves its value.')
search('Change only the third TODO to DONE.','TODO docs\nTODO tests\nTODO release\nTODO cleanup','TODO docs\nTODO tests\nDONE release\nTODO cleanup','/TODO<Enter>nciwDONE<Esc>','From the first TODO, /TODO finds the second. n reaches the third.','Search starts after the cursor. Know which match you begin on before counting further matches.')
search('Change the first “cat” animal, leaving “catalog” intact.','catalog\ncat\ncatfish','catalog\ndog\ncatfish','/cat<Enter>ciwdog<Esc>','/cat reaches the next occurrence after the cursor: the standalone second-line word.','A plain search can match inside longer words; cursor position matters. Whole-word searches are useful when you want to exclude those matches.')
search('Rename the next standalone “port”, keeping “portal”.','port = 80\nportal = true\nport = 443','port = 80\nportal = true\nendpoint = 443','*ciwendpoint<Esc>','With the cursor on port, * finds the next whole-word match.','The word search skips portal automatically.')
search('Change the preceding standalone “item” to “entry”.','item = first\nitemCount = 2\nitem = last','entry = first\nitemCount = 2\nitem = last','#ciwentry<Esc>','# searches backward for the current whole word.','Backward whole-word search skips itemCount just as forward search does.',(2,0))
search('Capitalize the heading that starts with “release”.','notes about release\nrelease notes\nprevious release','notes about release\nRELEASE notes\nprevious release','/^release<Enter>gUiw','Search for ^release, then uppercase the word.','^ anchors a pattern to the beginning of a line, excluding prose that mentions the same word.')
search('Replace only the final “pending” status on its line.','pending review\nstatus: pending\npending queue','pending review\nstatus: ready\npending queue','/pending$<Enter>ciwready<Esc>','Search for pending$ and change the word.','$ anchors the match to the end of a line.')
search('Delete the empty separator between the two settings.','host=local\n\nport=8080','host=local\nport=8080','/^$<Enter>dd','/^$ finds a line with nothing between its start and end. Then dd removes it.','Anchors together distinguish a genuinely empty line from a line containing spaces.')
search('Change the ERROR record’s code from 500 to 503.','INFO code=200\nERROR code=500\nWARN code=429','INFO code=200\nERROR code=503\nWARN code=429','/^ERROR<Enter>f=lciw503<Esc>','Find ^ERROR, then f=l moves inside the value after the equals sign.','Combine a broad search with a local character motion to reach a precise field.')
search('Replace the quoted value on the “region” line with “east”.','mode="dev"\nregion="west"\nlabel="west"','mode="dev"\nregion="east"\nlabel="west"','/^region<Enter>ci"east<Esc>','Search for ^region, then ci" changes its quoted value.','Search by a stable key rather than by a value that appears elsewhere.')
search('Remove the line marked “deprecated”.','start()\nlegacy() // deprecated\nfinish()','start()\nfinish()','/deprecated<Enter>dd','Search for the marker and delete its entire line.','The matching text can serve as a landmark for a larger linewise operation.')
search('Add a semicolon to the return statement.','function get() {\n  return value\n}','function get() {\n  return value;\n}','/return<Enter>A;<Esc>','Find return, then A appends at the end of its line.','Navigation and editing can use different units: a word search followed by a line-boundary insertion.')
search('Change the last of the three “draft” labels to “final”.','draft intro\ndraft body\ndraft appendix','draft intro\ndraft body\nfinal appendix','*nciwfinal<Esc>','* finds the next draft. n moves in the same direction to the last.','n repeats the search without rebuilding its pattern.')
search('Change the middle “draft” label to “final”.','draft intro\ndraft body\ndraft appendix','draft intro\nfinal body\ndraft appendix','*nNciwfinal<Esc>','Use * then n to reach the last match; N steps back to the middle.','N reverses the direction of the current search for a single movement.')
search('Rename all three standalone “old”, preserving “older”.','old = older\nuse(old)\nreturn old','fresh = older\nuse(fresh)\nreturn fresh','*Nciwfresh<Esc>n.n.','Create the whole-word search with *, return with N, change the word, then n. twice.','Search plus dot repeats a structural edit while preserving longer identifiers.')
search('Find the version number and increase it by one.','name: widget\nversion: 9\nworkers: 3','name: widget\nversion: 10\nworkers: 3','/^version<Enter>f:l<C-a>','Find the version key, move past its colon, then Ctrl+a.','Ctrl+a finds the next number on the line, even if the cursor is on the space before it.')
search('Change the TODO after the test section to DONE.','TODO docs\n[tests]\nTODO cases\nTODO cleanup','TODO docs\n[tests]\nDONE cases\nTODO cleanup','/TODO<Enter>ciwDONE<Esc>','From the tests heading, /TODO reaches the first TODO below it.','The initial cursor is part of a search task. Start from a known section to avoid touching earlier matches.',(1,0))
search('Remove the comment line beginning with “# temporary”.','value=1\n# temporary workaround\nlabel="# temporary"\nvalue=2','value=1\nlabel="# temporary"\nvalue=2','/^# temporary<Enter>dd','Use the anchored pattern ^# temporary, then dd.','Anchoring protects a quoted value that happens to contain the same text.')
search('Replace only the exact “stop” line with “continue”.','stopwatch\nstop\nstop now','stopwatch\ncontinue\nstop now','/^stop$<Enter>cccontinue<Esc>','Search for ^stop$ and change the line.','Using both anchors restricts a match to the entire line.')
search('Uppercase the failed status without changing its message.','ok cached\nfailed database timeout\nok served','ok cached\nFAILED database timeout\nok served','/^failed<Enter>gUiw','Search for ^failed and apply gUiw.','An operator plus text object can act directly at a search result without entering Insert mode.')
# Twenty-five substitutions/global filters, with guarded scopes and realistic data.
def ex(title,before,after,command,hint,why,cursor=(0,0)):
    add('Substitution' if 's/' in command or 's#' in command else 'Global commands',title,before,after,':'+command+'<Enter>',hint,why,cursor)
ex('Update every “localhost” host to “127.0.0.1”.','http://localhost:8080\nws://localhost:9000','http://127.0.0.1:8080\nws://127.0.0.1:9000','%s/localhost/127.0.0.1/g','Use :%s/localhost/127.0.0.1/g.','% sets the line range; g includes every matching occurrence within each line.')
ex('Replace every tab with two spaces.','name\tvalue\nport\t8080','name  value\nport  8080',r'%s/\t/  /g',r'Use :%s/\t/  /g with two spaces in the replacement.','Tabs are characters, not a fixed number of visible columns. The pattern matches the character itself.')
ex('Remove trailing spaces from every line.','alpha  \nbeta \ngamma','alpha\nbeta\ngamma','%s/  *$//','Use :%s/  *$// — two spaces before the star.','A space followed by space-star matches one or more spaces. The end anchor preserves indentation and internal spaces.')
ex('Remove the “temp_” prefix at the start of each line.','temp_user\ntemp_team\nkeep_temp_value','user\nteam\nkeep_temp_value','%s/^temp_//','Use :%s/^temp_//.','The start anchor prevents a prefix cleanup from damaging an occurrence inside a name.')
ex('Remove the “.bak” suffix from the filenames.','config.json.bak\narchive.bak.txt\nnotes.md.bak','config.json\narchive.bak.txt\nnotes.md',r'%s/\.bak$//',r'Use :%s/\.bak$//. Escape the dot and anchor the suffix.','An unescaped dot means any character. A suffix pattern should also be anchored so middle occurrences survive.')
ex('Normalize every semicolon separator to a comma.','name;email;role\nAda;ada@example.com;admin','name,email,role\nAda,ada@example.com,admin','%s/;/,/g','Use :%s/;/,/g.','The global flag matters when a single row has several separators.')
ex('Change only the first comma on each row to a colon.','name,email,role\nAda,ada@example.com,admin','name:email,role\nAda:ada@example.com,admin','%s/,/:/','Use :%s/,/:/ without g.','Omitting g is a useful constraint when the first field has a special role.')
ex('Enable the two worker flags, leaving global and legacy flags alone.','global=false\nworkerA=false\nworkerB=false\nlegacy=false','global=false\nworkerA=true\nworkerB=true\nlegacy=false','2,3s/false/true/','Use :2,3s/false/true/.','A line range protects matching settings outside the requested section.')
ex('Replace all “dev” on this line only.','dev-api dev-worker\ndev-docs','prod-api prod-worker\ndev-docs','s/dev/prod/g','Use :s/dev/prod/g.','g broadens matches within the current line; it does not broaden the line range.')
ex('Replace “draft” from this line through the end.','draft cover\ndraft body\ndraft appendix','draft cover\nfinal body\nfinal appendix','.,$s/draft/final/','Use :.,$s/draft/final/.','. means the current line and $ means the last line. The earlier cover stays untouched.',(1,0))
ex('Remove a leading “> ” quote marker from each line.','> quoted paragraph\n> another line\nx > y','quoted paragraph\nanother line\nx > y','%s/^> //','Use :%s/^> //.','The pattern includes the marker’s following space but only at line start.')
ex('Add “- ” to the beginning of every item.','apples\npears\nplums','- apples\n- pears\n- plums','%s/^/- /','Use :%s/^/- /.','A zero-width start anchor inserts text without consuming any existing characters.')
ex('Add a semicolon at the end of every statement.','load()\nrender()\nsave()','load();\nrender();\nsave();','%s/$/;/','Use :%s/$/;/.','An end anchor is a zero-width insertion point, even when line lengths differ.')
ex('Change every HTTPS URL to HTTP in this test fixture.','https://a.test\nhttps://b.test','http://a.test\nhttp://b.test','%s#https://#http://#g','Use # as the delimiter: :%s#https://#http://#g.','An alternate delimiter keeps slash-heavy URL patterns readable.')
ex('Move the asset paths from “/old/” to “/static/”.','/old/logo.svg\n/old/theme.css\n/archive/logo.svg','/static/logo.svg\n/static/theme.css\n/archive/logo.svg','%s#^/old/#/static/#','Use :%s#^/old/#/static/#.','Alternate delimiters and an anchor make a path migration precise without a forest of escapes.')
ex('Replace literal dots with slashes in the package names.','com.example.app\norg.example.lib','com/example/app\norg/example/lib',r'%s/\./\//g',r'Use :%s/\./\//g. The first escape makes the dot literal; the second protects the slash delimiter.','Pattern escaping and delimiter escaping solve different problems.')
ex('Replace digits with “#” in the account labels.','acct-42\nteam-7\nplain','acct-##\nteam-#\nplain','%s/[0-9]/#/g','Use :%s/[0-9]/#/g.','A character class matches each digit individually; g replaces all of them.')
ex('Remove carriage-return markers written as “<CR>”.','alpha<CR>\nbeta<CR>','alpha\nbeta','%s/<CR>//g','Use :%s/<CR>//g with an empty replacement.','An empty replacement deletes only the matched text. These are literal visible markers, not hidden carriage returns.')
ex('Change “color” to “colour” in the first two lines only.','color: red\nborder-color: blue\ncolor: legacy','colour: red\nborder-colour: blue\ncolor: legacy','1,2s/color/colour/g','Use :1,2s/color/colour/g.','A numeric range and g control two independent dimensions: which lines and how many matches per line.')
ex('Delete all empty lines.','alpha\n\nbeta\n\ngamma','alpha\nbeta\ngamma','g/^$/d','Use :g/^$/d.','Global applies a command to matching lines. Here the pattern matches only empty lines.')
ex('Delete every comment line that starts with “#”.','# generated\nport=8080\n# temporary\nname="#tag"','port=8080\nname="#tag"','g/^#/d','Use :g/^#/d.','Anchoring to the first character preserves a hash inside a setting value.')
ex('Delete only HTTP 404 records.','200 /home\n404 /missing\n500 /api\n404 /old\n200 /about','200 /home\n500 /api\n200 /about','g/^404 /d','Use :g/^404 /d with a space after the status.','Match the structured status field rather than any occurrence of 404 in a path.')
ex('Remove every line containing the deprecated API name.','use(newApi)\nuse(oldApi)\nwrap(oldApi)\nfinish()','use(newApi)\nfinish()','g/oldApi/d','Use :g/oldApi/d.','Without anchors, the pattern finds the deprecated name anywhere on a line.')
ex('Delete only disabled settings ending in “=off”.','cache=off\nmode=offline\nsearch=on\nexport=off\nkeep=on','mode=offline\nsearch=on\nkeep=on','g/=off$/d','Use :g/=off$/d.','The end anchor distinguishes the value off from the longer value offline.')
ex('Remove the three-line diagnostic block, keeping the footer.','header\ntrace one\ntrace two\ntrace three\nfooter','header\nfooter','2,4d','Use :2,4d.','Ex ranges can delete a contiguous block directly, with no visual selection or repeated dd.')
# Fifteen register, selection and indentation tasks.
add('Registers','Copy “customerId” into the empty lookup call.','customerId\nlookup()','customerId\nlookup(customerId)','yiwjf(p','Yank the identifier with yiw, then jf(p puts it after the opening parenthesis.','A characterwise yank can be pasted into another structure without copying a whole line.')
add('Registers','Replace “old” with the copied “primary” label.','primary\nrole=old','primary\nrole=primary','yiwjf=lviwp','Yank primary, move inside old, select it with viw, then p.','Putting over a visual selection replaces just the selected region with the yanked text.')
add('Registers','Copy the quoted hostname into the second setting.','host="api.internal"\nbackup=""','host="api.internal"\nbackup="api.internal"','yi"jf"p','Yank inside the first quotes, move to the opening quote on the next line, and p.','The inner quote object copies the value without duplicating its delimiters.')
add('Registers','Move the warning line below the info line.','WARN retry\nINFO boot\nEND','INFO boot\nWARN retry\nEND','ddp','dd cuts the current line; p places it below the next line.','Linewise puts insert complete rows, including their line boundary.')
add('Registers','Duplicate the two-line request above the separator.','GET /health\nHost: local\n---','GET /health\nHost: local\nGET /health\nHost: local\n---','2yyjp','Yank two lines with 2yy, move to the second line, then p.','A count on yy collects a multi-line block in one register.')
add('Registers','Copy the header below the body while deleting the obsolete row.','HEADER\nobsolete\nbody\nEND','HEADER\nbody\nHEADER\nEND','"ayyjdd"ap','Save the header in register a, delete obsolete, then put from a.','A named register keeps important text safe when another deletion changes the unnamed register.')
add('Registers','Delete the draft row, then paste the original yank below the body.','TITLE\ndraft\nbody\nEND','TITLE\nbody\nTITLE\nEND','yyjdd"0p','Yank TITLE, delete draft, then use "0p.','Register 0 retains the most recent yank even after a deletion replaces the unnamed register.')
add('Registers','Remove the temporary row without losing the copied command.','run()\ntemporary\nfinish()\nEND','run()\nfinish()\nrun()\nEND','yyj"_ddp','Yank run(), delete temporary into the black-hole register with "_dd, then p.','The black-hole register discards text without disturbing the unnamed register.')
add('Visual editing','Uppercase the entire two-line warning.','warning: low disk\nclean up files\nkeep this normal','WARNING: LOW DISK\nCLEAN UP FILES\nkeep this normal','VjU','Vj selects both lines; U uppercases the selection.','Visual line mode makes a multi-line case operation explicit.')
add('Visual editing','Lowercase the two HTTP header names and values.','HOST: LOCAL\nACCEPT: JSON\nBODY','host: local\naccept: json\nBODY','Vju','Vj selects two lines; u lowercases them.','In Visual mode, u changes case; in Normal mode it means undo.')
add('Indentation','Indent all three statements one level.','if (ready) {\nload();\ncheck();\nsend();\n}','if (ready) {\n  load();\n  check();\n  send();\n}','3>>','Use 3>> to shift three lines starting at the cursor.','A count on the doubled shift operator specifies the number of lines.',(1,0))
add('Indentation','Dedent both statements one level.','if (ready) {\n    load();\n    send();\n}','if (ready) {\n  load();\n  send();\n}','Vj<','Select both statements with Vj, then shift left with <.','Block dedentation preserves the statements while removing one shared indentation level.',(1,0))
add('Visual editing','Delete the first two fields, keeping “gamma”.','alpha beta gamma','gamma','v2wd','v starts characterwise selection; 2w reaches gamma; adjust the selection to exclude it.','For this target, an operator motion is simpler than a visual selection; d2w removes exactly two words.')
# Correct idiomatic solution for this task uses the operator directly.
rows[-1][5]=list('d2w');rows[-1][6]='Use d2w to delete two words and their following spaces.'
add('Marks','Copy the footer note below the marked section.','section\nbody\nseparator\nNOTE\nEND','section\nNOTE\nbody\nseparator\nNOTE\nEND','maGkyy\'ap','Set mark a on section; Gk reaches NOTE, yy copies it, and \'a returns before p.','A line mark lets you return to a destination after navigating elsewhere to collect text.')
add('Marks','Move the TODO line below the marked heading.','Tasks\nintro\nseparator\nTODO ship\nEND','Tasks\nTODO ship\nintro\nseparator\nEND','maGkdd\'ap','Mark Tasks with ma, cut TODO using Gkdd, return with \'a, then p.','Marks make nonadjacent line moves easier without needing to recalculate line numbers after a deletion.')
# Twenty composed edits: combine operators, objects, counts and numeric changes.
add('Composed edits','Change the function name and clear its arguments.','legacy(user, token);','refresh();','ciwrefresh<Esc>f(di(','Change the name with ciw, then find ( and use di(.','Separate edits can target separate semantic units: an identifier and an argument list.')
add('Composed edits','Turn the single-quoted value into an empty string.','name = \'temporary value\';','name = \'\';','di\'','Use di\' to delete inside single quotes.','An inner text object preserves the surrounding syntax, regardless of the value’s length.',(0,10))
add('Composed edits','Remove the optional bracketed annotation and its leading space.','deploy [dry-run] now','deploy now','f hdt]x','Find the space, move back only if needed; remove the annotation as a unit.','Deleting a surrounding annotation should also remove its extra separator.')
rows[-1][5]=['f','[','d','a','[','X'];rows[-1][6]='Find [ with f[, remove the bracket object with da[, then X removes the extra preceding space.'
add('Composed edits','Replace the list contents with “one, two”.','items = [legacy, obsolete, unused]','items = [one, two]','f[ci[one, two<Esc>','Find [, then ci[ replaces the contents.','A bracket object avoids counting the number or length of existing list entries.')
add('Composed edits','Rename both “send” calls to “dispatch”.','send(user)\nsend(team)','dispatch(user)\ndispatch(team)','ciwdispatch<Esc>j0.','Change the first name, move to the next line’s start, and repeat with dot.','Dot repeats the change, not the intervening cursor motion.')
add('Composed edits','Remove “await ” from both calls.','await load();\nawait save();','load();\nsave();','dawj0.','Use daw, then j0 and dot.','Resetting to the beginning of the next line makes the repeated deletion predictable.')
add('Composed edits','Add “return ” before both calls.','load();\nsave();','return load();\nreturn save();','Ireturn <Esc>j.','Use Ireturn and a space, Escape, then j and dot.','I records an insertion at the first nonblank character, so the repeat keeps existing indentation.')
add('Composed edits','Change both “enabled” values to “disabled”.','feature="enabled"\nbackup="enabled"','feature="disabled"\nbackup="disabled"','ci"disabled<Esc>j0.','Change inside quotes, move down and to column zero, then dot.','The quote object can locate the value ahead of the cursor on each line.')
add('Numbers','Increase the port by ten.','port=8080','port=8090','10<C-a>','Use 10 Ctrl+a with the cursor before the number.','A count controls the size of the numeric increment instead of requiring ten separate presses.')
add('Numbers','Decrease the cache limit by twenty-five.','cache_limit=128','cache_limit=103','25<C-x>','Use 25 Ctrl+x.','Numeric edits can apply a meaningful delta directly to a configuration value.')
add('Numbers','Roll the build counter from 999 to 1000.','build=999','build=1000','<C-a>','Ctrl+a increments the next number on the line.','The operation handles carries and adds a digit automatically.')
add('Character motions','Remove the namespace prefix, including its colon.','legacy:render(view)','render(view)','df:','Use df: to delete through the first colon.','f includes the found character when used as an operator motion.')
