# Replace overlapping drills with deeper techniques; retain exactly 100 new tasks.
def replace(title,topic,newtitle,before,after,keys,hint,why,cursor=(0,0)):
    idx=next(i for i,r in enumerate(rows) if r[1]==title)
    add(topic,newtitle,before,after,keys,hint,why,cursor)
    rows[idx]=rows.pop()
